 function clearResult(){motion?.clear();evaluated=null;highlight=[];hintText=level?.tutorial?guideText:'';hintTier=0;hintPlan=null;paletteCell=-1;message=game==='desvio'?'Selecione uma casa.':'Continue explorando. Confirme quando quiser conferir.';}
